window.kbPageData["views/entry/k-11296a74810194e8"] = {"key":"entry/k-11296a74810194e8","state":{"route":"entry/k-11296a74810194e8"},"node":{"id":"k-11296a74810194e8","mode":"k","title":"等高三角形的面积比","type":"原理与机制","domain":"数学","reading":"","intro":"","priority":100,"aliases":["等高三角形的面积比等于底边长之比","等高三角形的面积比等于对应底边长度比","等高三角形的面积比等于对应底边长之比"],"qs":["国考 2023 副省级 行测#64","国考 2023 地市级 行测#65","国考 2023 行政执法 行测#65"],"current":false,"candidates":true,"sources":[],"basisGroup":"","authority":null,"sourceOnly":false,"reviewSet":"单次条目","independentCount":2,"repeatPositions":1,"directorySummary":"当两个三角形相对于各自所取底边的高相等时，它们的面积比等于这两条底边的长度比。","review":{"definition":"当两个三角形相对于各自所取底边的高相等时，它们的面积比等于这两条底边的长度比。","explanation":"三角形EOD与三角形EOF共用顶点E，底边OD、OF同在直线FD上，且OD∶OF=1∶2，所以人工湖面积为1时，三角形EOF的面积为2。再加上三角形COF的面积4，得三角形EFC的面积为6。三角形AEC、EFC、FBC共用顶点C，底边AE、EF、FB等长，因此公园总面积是三角形EFC面积的3倍，即人工湖面积的18倍。","references":[],"evidence":"高相同，底边DO：FO=1：2","disposition":"独立词条","basis":"据原题和解析编释。","title":"等高三角形的面积比","related":[],"examFocus":{"国考 2023 副省级 行测#64":"沿图中同一直线找出等高三角形，按底边之比逐步比较湖区和其余各部分面积。","国考 2023 地市级 行测#65":"用对角线上的线段比比较等高三角形的面积，再结合剩余面积、单人日修剪量和已有工人数判断需增派多少人。"}},"readings":[{"origin":"k-11296a74810194e8","title":"等高三角形的面积比","qs":["国考 2023 副省级 行测#64"],"definition":"当两个三角形相对于各自所取底边的高相等时，它们的面积比等于这两条底边的长度比。","explanation":"三角形EOD与三角形EOF共用顶点E，底边OD、OF同在直线FD上，且OD∶OF=1∶2，所以人工湖面积为1时，三角形EOF的面积为2。再加上三角形COF的面积4，得三角形EFC的面积为6。三角形AEC、EFC、FBC共用顶点C，底边AE、EF、FB等长，因此公园总面积是三角形EFC面积的3倍，即人工湖面积的18倍。","evidence":"高相同，底边DO：FO=1：2","doubt":"","references":[]},{"origin":"k-38c3527be2fcb3ca","title":"等高三角形的面积比","qs":["国考 2023 行政执法 行测#65"],"definition":"三角形面积等于底乘以对应的高的一半。两个三角形对应的高相等时，面积比等于底边长度比。","explanation":"以 AOB 的面积为 1。AOD 与 AOB 共用顶点 A，底边都在 BD 所在直线上，因此等高，面积比为 DO∶BO＝4∶2，所以 AOD 的面积为 2。分别以 B、D 为共同顶点，沿 AC 所在直线比较底边，得 BOC 的面积为 3，COD 的面积为 6。剩余三个区域的总面积是 AOB 的 11 倍，第二天共需 11 名工人，在原有 1 名工人的基础上至少增派 10 名，选 B。","evidence":"两个三角形的高相同，面积之比等于底之比","doubt":"","references":[]},{"origin":"k-e7a6ae39aff5b3a7","title":"等高三角形的面积比","qs":["国考 2023 地市级 行测#65"],"definition":"两个三角形对所选底边的高相等时，面积之比等于这两条底边的长度之比，因为面积公式中的高和二分之一可以约去。","explanation":"第65题相邻两块三角形可用同一条对角线上的两段作底，另一条对角线上的同一顶点到该底边所在直线的距离是共同的高。由AO∶CO＝1∶3、BO∶DO＝1∶2，得AOB、BOC、COD、DOA的面积比为1∶3∶6∶2。剩余面积是AOB的11倍，第二天共需11名同效率工人，在原有1名工人基础上还需增加10名。","evidence":"两个三角形的高相同，面积之比等于底之比","doubt":"","references":[]}]},"questions":{"国考 2023 副省级 行测#64":{"paper":"国考 2023 副省级 行测","n":64,"mod":"数量关系","src":["503793642e845de9795f.pdf",12],"asrc":["ecade1ff5af69283232e.pdf",20],"card":"2e0de00cfb22e7971a29df45","links":[{"id":"k-11296a74810194e8","role":"解题依据","why":"利用共高三角形的底边长比例推算分块面积，并将分块面积扩展到全图。"}]},"国考 2023 地市级 行测#65":{"paper":"国考 2023 地市级 行测","n":65,"mod":"数量关系","src":["64bc3a15d27a04e94940.pdf",11],"asrc":["f3ab652d8e31c5bbdabc.pdf",20],"card":"497a6e432b646866db795414","links":[{"id":"k-11296a74810194e8","role":"解题依据","why":"对角线分出的相邻三角形可取等高的对应底边，由线段比推出各块面积比。"}]},"国考 2023 行政执法 行测#65":{"paper":"国考 2023 行政执法 行测","n":65,"mod":"数量关系","src":["857378cf496f27296500.pdf",11],"asrc":["d23139fe5a0fb3115135.pdf",20],"card":"e8e48bcdd1bf70b5935a4dfb","links":[{"id":"k-11296a74810194e8","role":"解题依据","why":"对角线分出的相邻三角形可取同一直线上的两段为底，获得相对于基准区域的面积比。"}]}},"terms":{},"references":{},"topics":[],"units":{"k-11296a74810194e8":[["国考 2023 副省级 行测#64"],["国考 2023 地市级 行测#65","国考 2023 行政执法 行测#65"]]}};
